-- Yardımcılar ---------------------------------------------------------------
-- studsPerMeter: 1/0.28 = 3.571 (Roblox karakter ölçeği) veya 3.28084 (1 stud = 1 ft)
function M.toStuds(xm, ym, zm, studsPerMeter, vScale)
	local k = studsPerMeter or (1 / 0.28)
	return Vector3.new(xm * k, ym * k * (vScale or 1), zm * k)
end
function M.pointAt(i, studsPerMeter, vScale)
	return M.toStuds(M.X[i], M.Y[i], M.Z[i], studsPerMeter, vScale)
end
-- kilometrajdan (m) konum: doğrusal ara değer
function M.positionAtChainage(sm, studsPerMeter, vScale)
	local n = #M.S
	if sm <= 0 then return M.pointAt(1, studsPerMeter, vScale) end
	if sm >= M.S[n] then return M.pointAt(n, studsPerMeter, vScale) end
	local i = math.clamp(math.floor(sm / M.Step) + 1, 1, n - 1)
	while M.S[i + 1] < sm do i += 1 end
	while M.S[i] > sm do i -= 1 end
	local t = (sm - M.S[i]) / (M.S[i + 1] - M.S[i])
	return M.pointAt(i, studsPerMeter, vScale):Lerp(M.pointAt(i + 1, studsPerMeter, vScale), t)
end
return M